// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { Btn, DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, FORMATTED_LINES, MINIFIED, QUERY } from './script'

function SqlLine({ line }: { line: string }) {
  const kw =
    /^(SELECT|FROM|WHERE|GROUP BY|ORDER BY|LIMIT|LEFT JOIN|JOIN|ON|AS|AND|OR|TRUE|FALSE|DESC|ASC)\b/i
  const parts = line.split(/(\s+)/)
  return (
    <p data-d="sql-line" className="whitespace-pre">
      {parts.map((part, index) =>
        kw.test(part.trim()) && part.trim() ? (
          <span key={index} className="text-violet">
            {part}
          </span>
        ) : (
          <span key={index}>{part}</span>
        ),
      )}
    </p>
  )
}

const build: Build = ({ tl, q, qa, step, final, move, click, wait, cursorOut }) => {
  step(0)
  tl.fromTo(q('raw'), { opacity: 0.5 }, { opacity: 1, duration: 0.35 }, 0.2)

  step(1, '+=0.35')
  move('format')
  click('format')
  tl.to(q('raw'), { opacity: 0, y: -8, duration: 0.3 }, '<')
  tl.set(q('formatted'), { opacity: 1 })
  tl.fromTo(
    qa('sql-line'),
    { opacity: 0, x: -14 },
    { opacity: 1, x: 0, duration: 0.4, stagger: 0.04, ease: 'expo.out' },
  )

  step(2, '+=0.45')
  move('dialect')
  click('dialect')
  tl.to(q('dialect-pill'), { scale: 1.05, duration: 0.15, yoyo: true, repeat: 1 }, '<')

  step(3, '+=0.4')
  move('minify')
  click('minify')
  tl.to(
    qa('sql-line'),
    { y: (index) => -index * 18, opacity: 0, duration: 0.4, stagger: 0.02, ease: 'power3.in' },
    '<',
  )
  tl.fromTo(
    q('min'),
    { opacity: 0, scaleX: 0.85 },
    { opacity: 1, scaleX: 1, duration: 0.35, ease: 'expo.out' },
    '-=0.08',
  )
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="SQL Toolkit formatting a PostgreSQL query and minifying it"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={
          <span
            data-d="dialect"
            className="rounded-full border border-line-strong px-2.5 py-1 text-[10px] text-ink-soft"
          >
            <span data-d="dialect-pill">PostgreSQL ▾</span>
          </span>
        }
      >
        <div className="flex h-full flex-col gap-3">
          <div className="relative min-h-0 flex-1 overflow-hidden rounded-xl border border-line bg-canvas/80 p-3 font-mono text-[10.5px] leading-[18px] text-ink-soft md:text-[11px] md:leading-[19px]">
            <p data-d="raw" className="absolute inset-3 break-all">
              {QUERY}
            </p>
            <div data-d="formatted" className="absolute inset-3 opacity-0">
              {FORMATTED_LINES.map((line, index) => (
                <SqlLine key={index} line={line} />
              ))}
            </div>
            <p data-d="min" className="absolute inset-x-3 top-3 origin-left break-all opacity-0">
              {MINIFIED}
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            <Btn d="format" primary>
              Format
            </Btn>
            <Btn d="minify">Minify</Btn>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
